 18→	"github.com/go-git/go-git/v5/plumbing/object"
 19→)
 20→
 21→// pushSessionsBranchCommon is the shared implementation for pushing session branches.
 22→// Used by both manual-commit and auto-commit strategies.
 23→// By default, session logs are pushed automatically alongside user pushes.
 24→// Configuration (stored in .entire/settings.json under strategy_options.push_sessions):
 25→//   - false: disable automatic pushing
 26→//   - true or not set: push automatically (default)
 27→func pushSessionsBranchCommon(remote, branchName string) error {
 28→	// Check if pushing is disabled
 29→	if isPushSessionsDisabled() {
 30→		return nil
 31→	}
 32→
 33→	repo, err := OpenRepository()
 34→	if err != nil {
 35→		return nil //nolint:nilerr // Hook must be silent on failure
 36→	}
 37→
 38→	// Check if branch exists locally
 39→	branchRef := plumbing.NewBranchReferenceName(branchName)
 40→	localRef, err := repo.Reference(branchRef, true)
 41→	if err != nil {
 42→		// No branch, nothing to push
 43→		return nil //nolint:nilerr // Expected when no sessions exist yet
 44→	}
 45→
 46→	// Check if there's actually something to push (local differs from remote)
 47→	if !hasUnpushedSessionsCommon(repo, remote, localRef.Hash(), branchName) {
 48→		// Nothing to push - skip silently
 49→		return nil
 50→	}
 51→
 52→	return doPushSessionsBranch(remote, branchName)
 53→}
 54→
 55→// hasUnpushedSessionsCommon checks if the local branch differs from the remote.
 56→// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
 57→func hasUnpushedSessionsCommon(repo *git.Repository, remote string, localHash plumbing.Hash, branchName string) bool {
 58→	// Check for remote tracking ref: refs/remotes/<remote>/<branch>
 59→	remoteRefName := plumbing.NewRemoteReferenceName(remote, branchName)
 60→	remoteRef, err := repo.Reference(remoteRefName, true)
 61→	if err != nil {
 62→		// Remote branch doesn't exist yet - we have content to push
 63→		return true
 64→	}
 65→
 66→	// If local and remote point to same commit, nothing to sync
 67→	// This is the only case where we skip - any difference needs handling
 68→	return localHash != remoteRef.Hash()
 69→}
 70→
 71→// isPushSessionsDisabled checks if push_sessions is disabled in settings.
 72→// Returns true if push_sessions is explicitly set to false.
 73→func isPushSessionsDisabled() bool {
 74→	s, err := settings.Load()
 75→	if err != nil {
 76→		return false // Default: push is enabled
 77→	}
 78→	return s.IsPushSessionsDisabled()
 79→}
 80→
 81→// doPushSessionsBranch pushes the sessions branch to the remote.
 82→func doPushSessionsBranch(remote, branchName string) error {
 83→	fmt.Fprintf(os.Stderr, "[entire] Pushing session logs to %s...\n", remote)
 84→
 85→	// Try pushing first
 86→	if err := tryPushSessionsCommon(remote, branchName); err == nil {
 87→		return nil
 88→	}
 89→
 90→	// Push failed - likely non-fast-forward. Try to fetch and merge.
 91→	fmt.Fprintf(os.Stderr, "[entire] Syncing with remote session logs...\n")
 92→
 93→	if err := fetchAndMergeSessionsCommon(remote, branchName); err != nil {
 94→		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync sessions: %v\n", err)
 95→		return nil // Don't fail the main push
 96→	}
 97→
 98→	// Try pushing again after merge
 99→	if err := tryPushSessionsCommon(remote, branchName); err != nil {
100→		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push sessions after sync: %v\n", err)
101→	}
102→
103→	return nil
104→}
105→
106→// tryPushSessionsCommon attempts to push the sessions branch.
107→func tryPushSessionsCommon(remote, branchName string) error {
108→	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
109→	defer cancel()
110→
111→	// Use --no-verify to prevent recursive hook calls
112→	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", remote, branchName)
113→	cmd.Stdin = nil // Disconnect stdin to prevent hanging in hook context
114→
115→	output, err := cmd.CombinedOutput()
116→	if err != nil {
117→		// Check if it's a non-fast-forward error (we can try to recover)
118→		if strings.Contains(string(output), "non-fast-forward") ||
119→			strings.Contains(string(output), "rejected") {
120→			return errors.New("non-fast-forward")
121→		}
122→		return fmt.Errorf("push failed: %s", output)
123→	}
124→	return nil
125→}
126→
127→// fetchAndMergeSessionsCommon fetches remote sessions and merges into local using go-git.
128→// Since session logs are append-only (unique cond-* directories), we just combine trees.
129→func fetchAndMergeSessionsCommon(remote, branchName string) error {
130→	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
131→	defer cancel()
132→
133→	// Use git CLI for fetch (go-git's fetch can be tricky with auth)
134→	fetchCmd := exec.CommandContext(ctx, "git", "fetch", remote, branchName)
135→	fetchCmd.Stdin = nil
136→	if output, err := fetchCmd.CombinedOutput(); err != nil {
137→		return fmt.Errorf("fetch failed: %s", output)
138→	}
139→
140→	repo, err := OpenRepository()
141→	if err != nil {
142→		return fmt.Errorf("failed to open git repository: %w", err)
143→	}
144→
145→	// Get local branch
146→	localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
147→	if err != nil {
148→		return fmt.Errorf("failed to get local ref: %w", err)
149→	}
150→	localCommit, err := repo.CommitObject(localRef.Hash())
151→	if err != nil {
152→		return fmt.Errorf("failed to get local commit: %w", err)
153→	}
154→	localTree, err := localCommit.Tree()
155→	if err != nil {
156→		return fmt.Errorf("failed to get local tree: %w", err)
157→	}
158→
159→	// Get remote (FETCH_HEAD)
160→	fetchHeadRef, err := repo.Reference(plumbing.ReferenceName("FETCH_HEAD"), true)
161→	if err != nil {
162→		return fmt.Errorf("failed to get FETCH_HEAD: %w", err)
163→	}
164→	remoteCommit, err := repo.CommitObject(fetchHeadRef.Hash())
165→	if err != nil {
166→		return fmt.Errorf("failed to get remote commit: %w", err)
167→	}
168→	remoteTree, err := remoteCommit.Tree()
169→	if err != nil {
170→		return fmt.Errorf("failed to get remote tree: %w", err)
171→	}
172→
173→	// Flatten both trees and combine entries
174→	// Session logs have unique cond-* directories, so no conflicts expected
175→	entries := make(map[string]object.TreeEntry)
176→	if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
177→		return fmt.Errorf("failed to flatten local tree: %w", err)
178→	}
179→	if err := checkpoint.FlattenTree(repo, remoteTree, "", entries); err != nil {
180→		return fmt.Errorf("failed to flatten remote tree: %w", err)
181→	}
182→
183→	// Build merged tree
184→	mergedTreeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
185→	if err != nil {
186→		return fmt.Errorf("failed to build merged tree: %w", err)
187→	}
188→
189→	// Create merge commit with both parents
190→	mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
191→		[]plumbing.Hash{localRef.Hash(), fetchHeadRef.Hash()},
192→		"Merge remote session logs")
193→	if err != nil {
194→		return fmt.Errorf("failed to create merge commit: %w", err)
195→	}
196→
197→	// Update branch ref
198→	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), mergeCommitHash)
199→	if err := repo.Storer.SetReference(newRef); err != nil {
200→		return fmt.Errorf("failed to update branch ref: %w", err)
201→	}
202→
203→	return nil
204→}
205→
206→// PushTrailsBranch pushes the entire/trails branch to the remote.
207→// Reuses the same push/sync logic as session branches.
208→// Skips pushing if trails are disabled in settings.
209→func PushTrailsBranch(remote string) error {
210→	if isTrailsDisabled() {
211→		return nil
212→	}
213→	return pushSessionsBranchCommon(remote, paths.TrailsBranchName)
214→}
215→
216→// isTrailsDisabled checks if trails are disabled in settings.
217→// Returns true if strategy_options.trails is explicitly set to false.
218→func isTrailsDisabled() bool {
219→	s, err := settings.Load()
220→	if err != nil {
221→		return false // Default: trails enabled
222→	}
223→	return s.IsTrailsDisabled()
224→}
225→
226→// createMergeCommitCommon creates a merge commit with multiple parents.
227→func createMergeCommitCommon(repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
228→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
229→	now := time.Now()
230→	sig := object.Signature{
231→		Name:  authorName,
232→		Email: authorEmail,
233→		When:  now,
234→	}
235→
236→	commit := &object.Commit{
237→		TreeHash:     treeHash,
238→		ParentHashes: parents,
239→		Author:       sig,
240→		Committer:    sig,
241→		Message:      message,
242→	}
243→
244→	obj := repo.Storer.NewEncodedObject()
245→	if err := commit.Encode(obj); err != nil {
246→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
247→	}
248→
249→	hash, err := repo.Storer.SetEncodedObject(obj)
250→	if err != nil {
251→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
252→	}
253→
254→	return hash, nil
255→}
