func runTrailEnable(w io.Writer) error {
	s, err := LoadEntireSettings()
	if err != nil {
		return fmt.Errorf("failed to load settings: %w", err)
	}

	if s.StrategyOptions != nil {
		delete(s.StrategyOptions, "trails")
	}

	if err := SaveEntireSettings(s); err != nil {
		return fmt.Errorf("failed to save settings: %w", err)
	}

	fmt.Fprintln(w, "Trails enabled.")
	return nil
}

func newTrailDisableCmd() *cobra.Command {
	var useProjectSettings bool

	cmd := &cobra.Command{
		Use:   "disable",
		Short: "Disable automatic trail creation and pushing",
		Long: `Disable trail auto-creation on session start and pushing the trails branch
on git push. Existing trails are preserved.

By default, writes to .entire/settings.local.json. Use --project to write to
.entire/settings.json instead.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runTrailDisable(cmd.OutOrStdout(), useProjectSettings)
		},
	}

	cmd.Flags().BoolVar(&useProjectSettings, "project", false, "Write to .entire/settings.json instead of .entire/settings.local.json")
	return cmd
}

func runTrailDisable(w io.Writer, useProjectSettings bool) error {
	s, err := LoadEntireSettings()
	if err != nil {
		return fmt.Errorf("failed to load settings: %w", err)
	}

	if s.StrategyOptions == nil {
		s.StrategyOptions = make(map[string]any)
	}
	s.StrategyOptions["trails"] = false

	if useProjectSettings {
		if err := SaveEntireSettings(s); err != nil {
			return fmt.Errorf("failed to save settings: %w", err)
		}
	} else {
		if err := SaveEntireSettingsLocal(s); err != nil {
			return fmt.Errorf("failed to save local settings: %w", err)
		}
	}

	fmt.Fprintln(w, "Trails disabled.")
	return nil
}

// defaultBaseBranch is the fallback base branch name when it cannot be determined.
const defaultBaseBranch = "main"

// AutoCreateTrail creates a trail automatically for the current branch if one doesn't exist.
// This is called during session start for non-main branches.
// If prompt is non-empty, its first line is used as the trail title instead of the branch name.
func AutoCreateTrail(repo *git.Repository, branchName, baseBranch, prompt string) error {
	store := trail.NewStore(repo)

	existing, err := store.FindByBranch(branchName)
	if err == nil && existing != nil {
		return nil // Trail already exists
	}

	trailID, err := trail.GenerateID()
	if err != nil {
		return fmt.Errorf("failed to generate trail ID: %w", err)
	}

	authorName, _ := checkpoint.GetGitAuthorFromRepo(repo)
	now := time.Now()

	title := titleFromPrompt(prompt)
	if title == "" {
		title = trail.HumanizeBranchName(branchName)
	}

	metadata := &trail.Metadata{
		TrailID:   trailID,
		Branch:    branchName,
		Base:      baseBranch,
		Title:     title,
		Status:    trail.StatusInProgress,
		Author:    authorName,
		Assignees: []string{},
		Labels:    []string{},
		CreatedAt: now,
		UpdatedAt: now,
	}

	if err := store.Write(metadata, nil, nil); err != nil {
		return fmt.Errorf("failed to create trail: %w", err)
	}

	fmt.Fprintf(os.Stderr, "[entire] Created trail for branch: %s\n", branchName)
	return nil
}

// titleFromPrompt extracts a trail title from the user's prompt.
// Uses the first line, trimmed and truncated to 80 characters.
// Returns empty string if prompt is empty.
func titleFromPrompt(prompt string) string {
	if prompt == "" {
		return ""
	}
	line, _, _ := strings.Cut(prompt, "\n")
	title := strings.TrimSpace(line)
	if len(title) > 80 {
		title = title[:77] + "..."
	}
	return title
}

// hasFlag is a simple helper that checks os.Args for --flag presence.
// Used to distinguish between "flag not provided" and "flag provided with empty value".
func hasFlag(name string) bool {
	for _, arg := range os.Args {
		if arg == "--"+name || strings.HasPrefix(arg, "--"+name+"=") {
			return true
		}
	}
	return false
}

func truncate(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	if maxLen <= 3 {
		return s[:maxLen]
	}
	return s[:maxLen-3] + "..."
}

func formatValidStatuses() string {
	statuses := trail.ValidStatuses()
	names := make([]string, len(statuses))
	for i, s := range statuses {
		names[i] = string(s)
	}
	return strings.Join(names, ", ")
}

func containsString(slice []string, s string) bool {
	for _, v := range slice {
		if v == s {
			return true
		}
	}
	return false
}

func removeString(slice []string, s string) []string {
	var result []string
	for _, v := range slice {
		if v != s {
			result = append(result, v)
		}
	}
	return result
}

