	// Determine base branch
	if base == "" {
		base = strategy.GetDefaultBranchName(repo)
		if base == "" {
			base = defaultBaseBranch
		}
	}

	// Determine branch — create and checkout if needed
	isDefault, currentBranch, _ := IsOnDefaultBranch()
	if branch == "" {
		if !isDefault {
			branch = currentBranch
		} else {
			// On default branch with no --branch flag: prompt for a new branch name
			var inputBranch string
			form := NewAccessibleForm(
				huh.NewGroup(
					huh.NewInput().
						Title("Branch name").
						Placeholder("feat/my-feature").
						Value(&inputBranch),
				),
			)
			if formErr := form.Run(); formErr != nil {
				return fmt.Errorf("form cancelled: %w", formErr)
			}
			inputBranch = strings.TrimSpace(inputBranch)
			if inputBranch == "" {
				return fmt.Errorf("branch name is required")
			}
			branch = inputBranch
		}
	}

	// Create and checkout the branch if it doesn't exist
	if branchNeedsCreation(repo, branch) {
		if err := createAndCheckoutBranch(branch); err != nil {
			return fmt.Errorf("failed to create branch %q: %w", branch, err)
		}
		fmt.Fprintf(w, "Created and checked out branch %s\n", branch)
	} else if currentBranch != branch {
		// Branch exists but we're not on it — don't switch
		fmt.Fprintf(errW, "Note: trail will be created for branch %q (not the current branch)\n", branch)
	}

	// Check if trail already exists for this branch
	store := trail.NewStore(repo)
	existing, err := store.FindByBranch(branch)
	if err == nil && existing != nil {
		fmt.Fprintf(w, "Trail already exists for branch %q (ID: %s)\n", branch, existing.TrailID)
		return nil
	}

	// Determine title
	if title == "" {
		defaultTitle := trail.HumanizeBranchName(branch)

		// Interactive mode if flags not provided
		if !hasFlag("title") {
			var inputTitle string
			form := NewAccessibleForm(
				huh.NewGroup(
					huh.NewInput().
						Title("Trail title").
						Placeholder(defaultTitle).
						Value(&inputTitle),
				),
			)
			if formErr := form.Run(); formErr != nil {
				return fmt.Errorf("form cancelled: %w", formErr)
			}
			if inputTitle != "" {
				title = inputTitle
			} else {
				title = defaultTitle
			}
		} else {
			title = defaultTitle
		}
	}

	// Determine status
	var trailStatus trail.Status
	if statusStr != "" {
		trailStatus = trail.Status(statusStr)
		if !trailStatus.IsValid() {
			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
		}
	} else {
		trailStatus = trail.StatusDraft
	}

	// Generate trail ID
	trailID, err := trail.GenerateID()
	if err != nil {
		return fmt.Errorf("failed to generate trail ID: %w", err)
	}

	// Get git author
	authorName, _ := checkpoint.GetGitAuthorFromRepo(repo)

	now := time.Now()
	metadata := &trail.Metadata{
		TrailID:     trailID,
		Branch:      branch,
		Base:        base,
		Title:       title,
		Description: description,
		Status:      trailStatus,
		Author:      authorName,
		Assignees:   []string{},
		Labels:      []string{},
		CreatedAt:   now,
		UpdatedAt:   now,
	}

	if err := store.Write(metadata, nil, nil); err != nil {
		return fmt.Errorf("failed to create trail: %w", err)
	}

	fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", title, branch, trailID)
	return nil
}

