106→func runTrailListAll(w io.Writer, statusFilter string, jsonOutput bool) error {
107→	// Fetch remote trails branch so we see trails from collaborators
108→	fetchTrailsBranch()
109→
110→	repo, err := strategy.OpenRepository()
111→	if err != nil {
112→		return fmt.Errorf("failed to open repository: %w", err)
113→	}
114→
115→	store := trail.NewStore(repo)
116→	trails, err := store.List()
117→	if err != nil {
118→		return fmt.Errorf("failed to list trails: %w", err)
119→	}
120→
121→	if trails == nil {
122→		trails = []*trail.Metadata{}
123→	}
124→
125→	// Apply status filter
126→	if statusFilter != "" {
127→		status := trail.Status(statusFilter)
128→		if !status.IsValid() {
129→			return fmt.Errorf("invalid status %q: valid values are %s", statusFilter, formatValidStatuses())
130→		}
