135→			}
136→		}
137→		trails = filtered
138→	}
139→
140→	// Sort by updated_at descending
141→	sort.Slice(trails, func(i, j int) bool {
142→		return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
143→	})
144→
145→	if jsonOutput {
146→		enc := json.NewEncoder(w)
147→		enc.SetIndent("", "  ")
148→		if err := enc.Encode(trails); err != nil {
149→			return fmt.Errorf("failed to encode JSON: %w", err)
150→		}
151→		return nil
152→	}
153→
154→	if len(trails) == 0 {
155→		fmt.Fprintln(w, "No trails found.")
156→		fmt.Fprintln(w)
157→		fmt.Fprintln(w, "Commands:")
