160→		fmt.Fprintln(w, "  entire trail update   Update trail metadata")
161→		return nil
162→	}
163→
164→	// Table output
165→	fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n", "BRANCH", "TITLE", "STATUS", "AUTHOR", "UPDATED")
166→	for _, t := range trails {
