198→//nolint:cyclop // sequential steps for creating a trail — splitting would obscure the flow
199→func runTrailCreate(w, errW io.Writer, title, description, base, branch, statusStr string, checkout bool) error {
200→	repo, err := strategy.OpenRepository()
201→	if err != nil {
202→		return fmt.Errorf("failed to open repository: %w", err)
203→	}
204→
205→	// Determine base branch
206→	if base == "" {
207→		base = strategy.GetDefaultBranchName(repo)
208→		if base == "" {
209→			base = defaultBaseBranch
210→		}
211→	}
212→
213→	_, currentBranch, _ := IsOnDefaultBranch() //nolint:errcheck // best-effort detection
214→	interactive := !hasFlag("title") && !hasFlag("branch")
215→
216→	if interactive {
217→		// Interactive flow: title → description → branch (derived) → status
218→		if err := runTrailCreateInteractive(&title, &description, &branch, &statusStr); err != nil {
219→			return err
220→		}
221→	} else {
222→		// Non-interactive: derive missing values from provided flags
223→		if branch == "" {
224→			if hasFlag("title") {
225→				branch = slugifyTitle(title)
226→			} else {
227→				branch = currentBranch
228→			}
229→		}
230→		if title == "" {
231→			title = trail.HumanizeBranchName(branch)
232→		}
233→	}
234→	if branch == "" {
235→		return errors.New("branch name is required")
236→	}
237→
238→	// Create the branch if it doesn't exist
239→	needsCreation := branchNeedsCreation(repo, branch)
240→	if needsCreation {
241→		if err := createBranch(repo, branch); err != nil {
242→			return fmt.Errorf("failed to create branch %q: %w", branch, err)
243→		}
244→		fmt.Fprintf(w, "Created branch %s\n", branch)
245→	} else if currentBranch != branch {
246→		fmt.Fprintf(errW, "Note: trail will be created for branch %q (not the current branch)\n", branch)
247→	}
248→
249→	// Check if trail already exists for this branch
250→	store := trail.NewStore(repo)
251→	existing, err := store.FindByBranch(branch)
252→	if err == nil && existing != nil {
253→		fmt.Fprintf(w, "Trail already exists for branch %q (ID: %s)\n", branch, existing.TrailID)
254→		return nil
255→	}
256→
257→	// Determine status
258→	var trailStatus trail.Status
259→	if statusStr != "" {
260→		trailStatus = trail.Status(statusStr)
261→		if !trailStatus.IsValid() {
262→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
263→		}
264→	} else {
265→		trailStatus = trail.StatusDraft
266→	}
267→
268→	// Generate trail ID
269→	trailID, err := trail.GenerateID()
270→	if err != nil {
271→		return fmt.Errorf("failed to generate trail ID: %w", err)
272→	}
273→
274→	// Get author (GitHub username, falls back to git user.name)
275→	authorName := getTrailAuthor(repo)
276→
277→	now := time.Now()
278→	metadata := &trail.Metadata{
279→		TrailID:     trailID,
280→		Branch:      branch,
281→		Base:        base,
282→		Title:       title,
283→		Description: description,
284→		Status:      trailStatus,
285→		Author:      authorName,
286→		Assignees:   []string{},
287→		Labels:      []string{},
288→		CreatedAt:   now,
289→		UpdatedAt:   now,
290→	}
291→
292→	if err := store.Write(metadata, nil, nil); err != nil {
293→		return fmt.Errorf("failed to create trail: %w", err)
294→	}
295→
296→	fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", title, branch, trailID)
297→
298→	// Push the branch and trail data to origin
299→	if needsCreation {
300→		if err := pushBranchToOrigin(branch); err != nil {
301→			fmt.Fprintf(errW, "Warning: failed to push branch: %v\n", err)
302→		} else {
303→			fmt.Fprintf(w, "Pushed branch %s to origin\n", branch)
304→		}
305→	}
306→	if err := strategy.PushTrailsBranch("origin"); err != nil {
307→		fmt.Fprintf(errW, "Warning: failed to push trail data: %v\n", err)
308→	}
309→
310→	// Checkout the branch if requested or prompted
311→	if needsCreation && currentBranch != branch {
312→		shouldCheckout := checkout
313→		if !shouldCheckout && !hasFlag("checkout") {
314→			// Interactive: ask whether to checkout
315→			form := NewAccessibleForm(
316→				huh.NewGroup(
317→					huh.NewConfirm().
318→						Title(fmt.Sprintf("Check out branch %s?", branch)).
319→						Value(&shouldCheckout),
320→				),
321→			)
322→			if formErr := form.Run(); formErr == nil && shouldCheckout {
323→				checkout = true
324→			}
325→		}
326→		if checkout {
327→			if err := CheckoutBranch(branch); err != nil {
328→				return fmt.Errorf("failed to checkout branch %q: %w", branch, err)
329→			}
330→			fmt.Fprintf(w, "Switched to branch %s\n", branch)
331→		}
332→	}
333→
334→	return nil
335→}
