359→func runTrailUpdate(w io.Writer, statusStr, title, description, branch string, labelAdd, labelRemove []string) error {
360→	repo, err := strategy.OpenRepository()
361→	if err != nil {
362→		return fmt.Errorf("failed to open repository: %w", err)
363→	}
364→
365→	// Determine branch
366→	if branch == "" {
367→		branch, err = GetCurrentBranch()
368→		if err != nil {
369→			return fmt.Errorf("failed to determine current branch: %w", err)
370→		}
371→	}
372→
373→	store := trail.NewStore(repo)
374→	metadata, err := store.FindByBranch(branch)
375→	if err != nil {
376→		return fmt.Errorf("failed to find trail: %w", err)
377→	}
378→	if metadata == nil {
379→		return fmt.Errorf("no trail found for branch %q", branch)
380→	}
381→
382→	// Interactive mode when no flags are provided
383→	noFlags := statusStr == "" && title == "" && description == "" && labelAdd == nil && labelRemove == nil
384→	if noFlags {
385→		// Build status options with current value as default
386→		// Exclude "done" (set on merge) and "closed" (requires permissions)
387→		var statusOptions []huh.Option[string]
388→		for _, s := range trail.ValidStatuses() {
389→			if s == trail.StatusDone || s == trail.StatusClosed {
390→				continue
391→			}
392→			label := string(s)
393→			if s == metadata.Status {
394→				label += " (current)"
395→			}
396→			statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
397→		}
398→		statusStr = string(metadata.Status)
399→		title = metadata.Title
400→		description = metadata.Description
401→
402→		form := NewAccessibleForm(
403→			huh.NewGroup(
404→				huh.NewSelect[string]().
405→					Title("Status").
406→					Options(statusOptions...).
407→					Value(&statusStr),
408→				huh.NewInput().
409→					Title("Title").
410→					Value(&title),
411→				huh.NewText().
412→					Title("Description").
413→					Value(&description),
414→			),
415→		)
416→		if formErr := form.Run(); formErr != nil {
417→			return fmt.Errorf("form cancelled: %w", formErr)
418→		}
419→	}
420→
421→	// Validate status if provided
422→	if statusStr != "" {
423→		status := trail.Status(statusStr)
424→		if !status.IsValid() {
425→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
426→		}
427→	}
428→
429→	err = store.Update(metadata.TrailID, func(m *trail.Metadata) {
430→		if statusStr != "" {
431→			m.Status = trail.Status(statusStr)
432→		}
433→		if title != "" {
434→			m.Title = title
435→		}
436→		if description != "" {
437→			m.Description = description
438→		}
439→		for _, l := range labelAdd {
440→			if !containsString(m.Labels, l) {
441→				m.Labels = append(m.Labels, l)
442→			}
443→		}
444→		for _, l := range labelRemove {
445→			m.Labels = removeString(m.Labels, l)
446→		}
447→	})
448→	if err != nil {
449→		return fmt.Errorf("failed to update trail: %w", err)
450→	}
451→
452→	fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
453→	return nil
454→}
