459→// AutoCreateTrail creates a trail automatically for the current branch if one doesn't exist.
460→// This is called during session start for non-main branches.
461→// If prompt is non-empty, its first line is used as the trail title instead of the branch name.
462→func AutoCreateTrail(repo *git.Repository, branchName, baseBranch, prompt string) error {
463→	store := trail.NewStore(repo)
464→
465→	existing, err := store.FindByBranch(branchName)
466→	if err == nil && existing != nil {
467→		return nil // Trail already exists
468→	}
469→
470→	trailID, err := trail.GenerateID()
471→	if err != nil {
472→		return fmt.Errorf("failed to generate trail ID: %w", err)
473→	}
474→
475→	authorName := getTrailAuthor(repo)
476→	now := time.Now()
477→
478→	title := titleFromPrompt(prompt)
479→	if title == "" {
