481→	}
482→
483→	metadata := &trail.Metadata{
484→		TrailID:   trailID,
485→		Branch:    branchName,
486→		Base:      baseBranch,
487→		Title:     title,
488→		Status:    trail.StatusInProgress,
489→		Author:    authorName,
490→		Assignees: []string{},
491→		Labels:    []string{},
492→		CreatedAt: now,
493→		UpdatedAt: now,
494→	}
495→
496→	if err := store.Write(metadata, nil, nil); err != nil {
