504→// titleFromPrompt extracts a trail title from the user's prompt.
505→// Uses the first line, trimmed and truncated to 80 characters.
506→// Returns empty string if prompt is empty.
507→func titleFromPrompt(prompt string) string {
508→	if prompt == "" {
509→		return ""
510→	}
511→	line, _, _ := strings.Cut(prompt, "\n")
512→	title := strings.TrimSpace(line)
513→	if len(title) > 80 {
514→		title = title[:77] + "..."
515→	}
516→	return title
517→}
518→
519→// hasFlag is a simple helper that checks os.Args for --flag presence.
520→// Used to distinguish between "flag not provided" and "flag provided with empty value".
521→func hasFlag(name string) bool {
522→	for _, arg := range os.Args {
523→		if arg == "--"+name || strings.HasPrefix(arg, "--"+name+"=") {
524→			return true
525→		}
526→	}
527→	return false
528→}
529→
530→func truncate(s string, maxLen int) string {
531→	if len(s) <= maxLen {
532→		return s
533→	}
534→	if maxLen <= 3 {
535→		return s[:maxLen]
536→	}
537→	return s[:maxLen-3] + "..."
538→}
539→
540→func formatValidStatuses() string {
541→	statuses := trail.ValidStatuses()
542→	names := make([]string, len(statuses))
543→	for i, s := range statuses {
544→		names[i] = string(s)
545→	}
546→	return strings.Join(names, ", ")
547→}
548→
549→func containsString(slice []string, s string) bool {
550→	for _, v := range slice {
551→		if v == s {
552→			return true
553→		}
554→	}
555→	return false
556→}
557→
558→func removeString(slice []string, s string) []string {
559→	var result []string
560→	for _, v := range slice {
561→		if v != s {
562→			result = append(result, v)
563→		}
564→	}
565→	return result
566→}
567→
568→// runTrailCreateInteractive runs the interactive form for trail creation.
569→// Prompts for title, description, branch (derived from title), and status.
570→func runTrailCreateInteractive(title, description, branch, statusStr *string) error {
571→	// Step 1: Title and description
572→	form := NewAccessibleForm(
573→		huh.NewGroup(
574→			huh.NewInput().
575→				Title("Trail title").
576→				Placeholder("What are you working on?").
577→				Value(title),
578→			huh.NewText().
579→				Title("Description (optional)").
580→				Value(description),
581→		),
582→	)
583→	if err := form.Run(); err != nil {
584→		return fmt.Errorf("form cancelled: %w", err)
585→	}
586→	*title = strings.TrimSpace(*title)
587→	if *title == "" {
588→		return errors.New("trail title is required")
589→	}
590→
591→	// Step 2: Branch (derived from title) and status
592→	suggested := slugifyTitle(*title)
593→	*branch = suggested
594→
595→	// Build status options, excluding done/closed
596→	var statusOptions []huh.Option[string]
597→	for _, s := range trail.ValidStatuses() {
598→		if s == trail.StatusDone || s == trail.StatusClosed {
599→			continue
600→		}
601→		statusOptions = append(statusOptions, huh.NewOption(string(s), string(s)))
602→	}
603→	if *statusStr == "" {
604→		*statusStr = string(trail.StatusDraft)
605→	}
606→
607→	form = NewAccessibleForm(
608→		huh.NewGroup(
609→			huh.NewInput().
610→				Title("Branch name").
611→				Placeholder(suggested).
612→				Value(branch),
613→			huh.NewSelect[string]().
614→				Title("Status").
615→				Options(statusOptions...).
616→				Value(statusStr),
617→		),
618→	)
619→	if err := form.Run(); err != nil {
620→		return fmt.Errorf("form cancelled: %w", err)
621→	}
622→	*branch = strings.TrimSpace(*branch)
623→	if *branch == "" {
624→		*branch = suggested
625→	}
626→	return nil
627→}
628→
629→// fetchTrailsBranch fetches the remote trails branch so we see trails from collaborators.
630→// Best-effort: silently ignores errors (e.g., no remote, no network).
631→func fetchTrailsBranch() {
632→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
633→	defer cancel()
634→	branchName := paths.TrailsBranchName
635→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
636→	//nolint:gosec // G204: branchName is a constant from paths package
637→	cmd := exec.CommandContext(ctx, "git", "fetch", "origin", refSpec)
638→	_ = cmd.Run() //nolint:errcheck // best-effort fetch
639→}
640→
641→// getTrailAuthor returns the GitHub username for the trail author.
642→// Falls back to git user.name if gh CLI is unavailable or not authenticated.
643→func getTrailAuthor(repo *git.Repository) string {
644→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
645→	defer cancel()
646→	cmd := exec.CommandContext(ctx, "gh", "api", "user", "-q", ".login")
647→	if output, err := cmd.Output(); err == nil {
648→		if login := strings.TrimSpace(string(output)); login != "" {
649→			return login
650→		}
651→	}
652→	name, _ := strategy.GetGitAuthorFromRepo(repo)
653→	return name
654→}
655→
656→// slugifyTitle converts a title string into a branch-friendly slug.
657→// Example: "Add user authentication" -> "add-user-authentication"
658→func slugifyTitle(title string) string {
659→	s := strings.ToLower(strings.TrimSpace(title))
660→	// Replace spaces and underscores with hyphens
661→	s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
662→	// Remove anything that's not alphanumeric, hyphen, or slash
663→	var b strings.Builder
664→	prevHyphen := false
665→	for _, r := range s {
666→		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
667→			b.WriteRune(r)
668→			prevHyphen = false
669→		} else if r == '-' && !prevHyphen {
670→			b.WriteRune('-')
671→			prevHyphen = true
672→		}
673→	}
674→	return strings.Trim(b.String(), "-")
675→}
676→
677→// branchNeedsCreation checks if a branch exists locally.
678→func branchNeedsCreation(repo *git.Repository, branchName string) bool {
679→	_, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
680→	return err != nil
681→}
682→
683→// createBranch creates a new local branch pointing at HEAD without checking it out.
684→func createBranch(repo *git.Repository, branchName string) error {
685→	head, err := repo.Head()
686→	if err != nil {
687→		return fmt.Errorf("failed to get HEAD: %w", err)
688→	}
689→	ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
690→	if err := repo.Storer.SetReference(ref); err != nil {
691→		return fmt.Errorf("failed to create branch ref: %w", err)
692→	}
693→	return nil
694→}
695→
696→// pushBranchToOrigin pushes a branch to the origin remote.
697→func pushBranchToOrigin(branchName string) error {
698→	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
699→	defer cancel()
700→	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "-u", "origin", branchName)
701→	if output, err := cmd.CombinedOutput(); err != nil {
702→		return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
703→	}
704→	return nil
705→}
