309→// Delete removes a trail from the entire/trails branch.
310→func (s *Store) Delete(trailID ID) error {
311→	ref, entries, err := s.getBranchEntries()
312→	if err != nil {
313→		return fmt.Errorf("failed to get branch entries: %w", err)
314→	}
315→
316→	basePath := trailID.Path() + "/"
317→
318→	// Remove entries for this trail
319→	found := false
320→	for path := range entries {
321→		if strings.HasPrefix(path, basePath) {
322→			delete(entries, path)
323→			found = true
324→		}
325→	}
326→	if !found {
327→		return fmt.Errorf("trail %s not found", trailID)
328→	}
329→
330→	// Build tree and commit
331→	newTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, entries)
332→	if err != nil {
333→		return fmt.Errorf("failed to build tree: %w", err)
334→	}
335→
336→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
337→	commitMsg := fmt.Sprintf("Delete trail: %s", trailID)
338→	commitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
339→	if err != nil {
340→		return fmt.Errorf("failed to create commit: %w", err)
341→	}
342→
343→	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.TrailsBranchName), commitHash)
344→	if err := s.repo.Storer.SetReference(newRef); err != nil {
345→		return fmt.Errorf("failed to update branch reference: %w", err)
346→	}
