Body: getBranchTree always prefers the local entire/trails branch when it exists, even if `origin/entire/trails` has newer data that was just fetched. After a local write, `entire trail list` (and FindByBranch/AutoCreateTrail) can miss collaborator trails unless a push-sync happens. Consider merging remote->local (similar to fetchAndMergeSessionsCommon) or reading a merged view when local and remote hashes differ.
```suggestion
	localRefName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
	localRef, localErr := s.repo.Reference(localRefName, true)

	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.TrailsBranchName)
	remoteRef, remoteErr := s.repo.Reference(remoteRefName, true)

	// Helper to load the tree for a given ref.
	loadTreeForRef := func(ref *plumbing.Reference) (*object.Tree, error) {
		commit, err := s.repo.CommitObject(ref.Hash())
		if err != nil {
			return nil, fmt.Errorf("failed to get commit: %w", err)
		}

		tree, err := commit.Tree()
		if err != nil {
			return nil, fmt.Errorf("failed to get tree: %w", err)
		}

		return tree, nil
	}

	// Helper to flatten the tree for a given ref into entries.
	loadEntriesForRef := func(ref *plumbing.Reference) (map[string]object.TreeEntry, error) {
		commit, err := s.repo.CommitObject(ref.Hash())
		if err != nil {
			return nil, fmt.Errorf("failed to get commit: %w", err)
		}

		tree, err := commit.Tree()
		if err != nil {
			return nil, fmt.Errorf("failed to get tree: %w", err)
		}

		entries := make(map[string]object.TreeEntry)
		if err := checkpoint.FlattenTree(s.repo, tree, "", entries); err != nil {
			return nil, fmt.Errorf("failed to flatten tree: %w", err)
		}

		return entries, nil
	}

	// If both refs are missing, report a not-found error.
	if localErr != nil && remoteErr != nil {
		return nil, fmt.Errorf("trails branch not found: %w", localErr)
	}

	// If we have only the local ref (and remote is missing or just not found), use local.
	if localErr == nil && (remoteErr != nil && errors.Is(remoteErr, plumbing.ErrReferenceNotFound)) {
		return loadTreeForRef(localRef)
	}

	// If we have only the remote ref (and local is missing or just not found), use remote.
	if remoteErr == nil && (localErr != nil && errors.Is(localErr, plumbing.ErrReferenceNotFound)) {
		return loadTreeForRef(remoteRef)
	}

	// If either ref lookup failed with an unexpected error, surface it.
	if localErr != nil && !errors.Is(localErr, plumbing.ErrReferenceNotFound) {
		return nil, fmt.Errorf("failed to get local trails branch: %w", localErr)
	}
	if remoteErr != nil && !errors.Is(remoteErr, plumbing.ErrReferenceNotFound) {
		return nil, fmt.Errorf("failed to get remote trails branch: %w", remoteErr)
	}

	// At this point, either:
	//   - both refs exist, or
	//   - exactly one exists but the other had a not-found error handled above.
	if localErr == nil && remoteErr == nil {
		// If both refs point to the same commit, just load once.
		if localRef.Hash() == remoteRef.Hash() {
			return loadTreeForRef(localRef)
		}

		// Hashes differ: build a merged view of local and remote entries.
		localEntries, err := loadEntriesForRef(localRef)
		if err != nil {
			return nil, err
		}

		remoteEntries, err := loadEntriesForRef(remoteRef)
		if err != nil {
			return nil, err
		}

		// Start from local entries and overlay remote entries so remote wins on conflicts.
		mergedEntries := make(map[string]object.TreeEntry, len(localEntries)+len(remoteEntries))
		for path, entry := range localEntries {
			mergedEntries[path] = entry
		}
		for path, entry := range remoteEntries {
			mergedEntries[path] = entry
		}

		newTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, mergedEntries)
		if err != nil {
			return nil, fmt.Errorf("failed to build merged trails tree: %w", err)
		}

		mergedTree, err := s.repo.TreeObject(newTreeHash)
		if err != nil {
			return nil, fmt.Errorf("failed to load merged trails tree: %w", err)
		}

		return mergedTree, nil
	}

	// Fallback: if only one ref exists and we didn't return earlier, prefer local.
	if localErr == nil {
		return loadTreeForRef(localRef)
	}

	return loadTreeForRef(remoteRef)
```

