func runTrailUpdate(w io.Writer, statusStr, title, body, branch string, labelAdd, labelRemove []string) error {
	repo, err := strategy.OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	// Determine branch
	if branch == "" {
		branch, err = GetCurrentBranch()
		if err != nil {
			return fmt.Errorf("failed to determine current branch: %w", err)
		}
	}

	store := trail.NewStore(repo)
	metadata, err := store.FindByBranch(branch)
	if err != nil {
		return fmt.Errorf("failed to find trail: %w", err)
	}
	if metadata == nil {
		return fmt.Errorf("no trail found for branch %q", branch)
	}

	// Interactive mode when no flags are provided
	noFlags := statusStr == "" && title == "" && body == "" && labelAdd == nil && labelRemove == nil
	if noFlags {
		// Build status options with current value as default.
		// Exclude "done" and "closed" unless the trail is already in that status
		// (otherwise the select would silently reset to the first option).
		var statusOptions []huh.Option[string]
		for _, s := range trail.ValidStatuses() {
			if (s == trail.StatusDone || s == trail.StatusClosed) && s != metadata.Status {
				continue
			}
			label := string(s)
			if s == metadata.Status {
				label += " (current)"
			}
			statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
		}
		statusStr = string(metadata.Status)
		title = metadata.Title
		body = metadata.Body

		form := NewAccessibleForm(
			huh.NewGroup(
				huh.NewSelect[string]().
					Title("Status").
					Options(statusOptions...).
					Value(&statusStr),
				huh.NewInput().
					Title("Title").
					Value(&title),
				huh.NewText().
					Title("Body").
					Value(&body),
			),
		)
		if formErr := form.Run(); formErr != nil {
			return fmt.Errorf("form cancelled: %w", formErr)
		}
	}

	// Validate status if provided
	if statusStr != "" {
		status := trail.Status(statusStr)
		if !status.IsValid() {
			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
		}
	}

	err = store.Update(metadata.TrailID, func(m *trail.Metadata) {
		if statusStr != "" {
			m.Status = trail.Status(statusStr)
		}
		if title != "" {
			m.Title = title
		}
		if body != "" {
			m.Body = body
		}
		for _, l := range labelAdd {
			if !containsString(m.Labels, l) {
				m.Labels = append(m.Labels, l)
			}
		}
		for _, l := range labelRemove {
			m.Labels = removeString(m.Labels, l)
		}
	})
	if err != nil {
		return fmt.Errorf("failed to update trail: %w", err)
	}

	fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
	return nil
}

// defaultBaseBranch is the fallback base branch name when it cannot be determined.
const defaultBaseBranch = "main"

// AutoCreateTrail creates a trail automatically for the current branch if one doesn't exist.
// This is called during session start for non-main branches.
// If prompt is non-empty, its first line is used as the trail title instead of the branch name.
func AutoCreateTrail(repo *git.Repository, branchName, baseBranch, prompt string) error {
	store := trail.NewStore(repo)

	existing, err := store.FindByBranch(branchName)
	if err == nil && existing != nil {
		return nil // Trail already exists
	}

	trailID, err := trail.GenerateID()
	if err != nil {
		return fmt.Errorf("failed to generate trail ID: %w", err)
	}

	authorName := getTrailAuthor(repo)
	now := time.Now()

	title := titleFromPrompt(prompt)
	if title == "" {
		title = trail.HumanizeBranchName(branchName)
	}

	metadata := &trail.Metadata{
		TrailID:   trailID,
		Branch:    branchName,
		Base:      baseBranch,
		Title:     title,
		Status:    trail.StatusInProgress,
		Author:    authorName,
		Assignees: []string{},
		Labels:    []string{},
		CreatedAt: now,
		UpdatedAt: now,
	}

	if err := store.Write(metadata, nil, nil); err != nil {
		return fmt.Errorf("failed to create trail: %w", err)
	}

	logCtx := context.Background()
	logging.Info(logCtx, "auto-created trail for branch",
		slog.String("branch", branchName),
		slog.String("trail_id", trailID.String()))
	return nil
}

// titleFromPrompt extracts a trail title from the user's prompt.
// Uses the first line, trimmed and truncated to 80 characters.
// Returns empty string if prompt is empty.
func titleFromPrompt(prompt string) string {
	if prompt == "" {
		return ""
	}
	line, _, _ := strings.Cut(prompt, "\n")
	title := strings.TrimSpace(line)
	if len(title) > 80 {
		title = title[:77] + "..."
	}
	return title
}

// hasFlag is a simple helper that checks os.Args for --flag presence.
// Used to distinguish between "flag not provided" and "flag provided with empty value".
func hasFlag(name string) bool {
	for _, arg := range os.Args {
		if arg == "--"+name || strings.HasPrefix(arg, "--"+name+"=") {
			return true
		}
	}
	return false
}

func truncate(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	if maxLen <= 3 {
		return s[:maxLen]
	}
	return s[:maxLen-3] + "..."
}

func formatValidStatuses() string {
	statuses := trail.ValidStatuses()
	names := make([]string, len(statuses))
	for i, s := range statuses {
		names[i] = string(s)
	}
	return strings.Join(names, ", ")
}

func containsString(slice []string, s string) bool {
	for _, v := range slice {
		if v == s {
			return true
		}
	}
	return false
}

func removeString(slice []string, s string) []string {
	var result []string
	for _, v := range slice {
		if v != s {
			result = append(result, v)
		}
	}
	return result
}

// runTrailCreateInteractive runs the interactive form for trail creation.
// Prompts for title, body, branch (derived from title), and status.
func runTrailCreateInteractive(title, body, branch, statusStr *string) error {
	// Step 1: Title and body
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewInput().
				Title("Trail title").
				Placeholder("What are you working on?").
				Value(title),
			huh.NewText().
				Title("Description (optional)").
				Value(description),
		),
	)
	if err := form.Run(); err != nil {
		return fmt.Errorf("form cancelled: %w", err)
	}
	*title = strings.TrimSpace(*title)
	if *title == "" {
		return errors.New("trail title is required")
	}

	// Step 2: Branch (derived from title) and status
	suggested := slugifyTitle(*title)
	*branch = suggested

	// Build status options, excluding done/closed
	var statusOptions []huh.Option[string]
	for _, s := range trail.ValidStatuses() {
		if s == trail.StatusDone || s == trail.StatusClosed {
			continue
		}
		statusOptions = append(statusOptions, huh.NewOption(string(s), string(s)))
	}
	if *statusStr == "" {
		*statusStr = string(trail.StatusDraft)
	}

	form = NewAccessibleForm(
		huh.NewGroup(
			huh.NewInput().
				Title("Branch name").
				Placeholder(suggested).
				Value(branch),
			huh.NewSelect[string]().
				Title("Status").
				Options(statusOptions...).
				Value(statusStr),
		),
	)
	if err := form.Run(); err != nil {
		return fmt.Errorf("form cancelled: %w", err)
	}
	*branch = strings.TrimSpace(*branch)
	if *branch == "" {
		*branch = suggested
	}
	return nil
}

// fetchTrailsBranch fetches the remote trails branch so we see trails from collaborators.
// Best-effort: silently ignores errors (e.g., no remote, no network).
func fetchTrailsBranch() {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	branchName := paths.TrailsBranchName
	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
	//nolint:gosec // G204: branchName is a constant from paths package
	cmd := exec.CommandContext(ctx, "git", "fetch", "origin", refSpec)
	// Ensure non-interactive fetch in hook/agent contexts
	cmd.Stdin = nil
	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
	_ = cmd.Run() //nolint:errcheck // best-effort fetch
}

// getTrailAuthor returns the GitHub username for the trail author.
// Falls back to git user.name if gh CLI is unavailable or not authenticated.
func getTrailAuthor(repo *git.Repository) string {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, "gh", "api", "user", "-q", ".login")
	if output, err := cmd.Output(); err == nil {
		if login := strings.TrimSpace(string(output)); login != "" {
			return login
		}
	}
	name, _ := strategy.GetGitAuthorFromRepo(repo)
	return name
}

// slugifyTitle converts a title string into a branch-friendly slug.
// Example: "Add user authentication" -> "add-user-authentication"
func slugifyTitle(title string) string {
	s := strings.ToLower(strings.TrimSpace(title))
	// Replace spaces and underscores with hyphens
	s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
	// Remove anything that's not alphanumeric, hyphen, or slash
	var b strings.Builder
	prevHyphen := false
	for _, r := range s {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
			b.WriteRune(r)
			prevHyphen = false
		} else if r == '-' && !prevHyphen {
			b.WriteRune('-')
			prevHyphen = true
		}
	}
	return strings.Trim(b.String(), "-")
}

// branchNeedsCreation checks if a branch exists locally.
func branchNeedsCreation(repo *git.Repository, branchName string) bool {
	_, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
	return err != nil
}

// createBranch creates a new local branch pointing at HEAD without checking it out.
func createBranch(repo *git.Repository, branchName string) error {
	head, err := repo.Head()
	if err != nil {
		return fmt.Errorf("failed to get HEAD: %w", err)
	}
	ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
	if err := repo.Storer.SetReference(ref); err != nil {
		return fmt.Errorf("failed to create branch ref: %w", err)
	}
	return nil
}

// pushBranchToOrigin pushes a branch to the origin remote.
func pushBranchToOrigin(branchName string) error {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
	defer cancel()
	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "-u", "origin", branchName)
	if output, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
	}
	return nil
}

package summarize

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// trailTitlePromptTemplate is the prompt used to generate trail titles and descriptions.
//
// Security note: The transcript is wrapped in <transcript> tags to provide clear boundary
// markers. This helps contain any potentially malicious content within the transcript.
const trailTitlePromptTemplate = `Analyze this development session transcript and generate a title and description.

<transcript>
%s
</transcript>

Return a JSON object:
{
  "title": "Short imperative title (max 80 chars)",
  "description": "1-3 sentence description of what was accomplished and why"
}

Guidelines:
- Title: imperative mood, captures core intent (e.g. "Add user authentication flow")
- Description: explain the "what" and "why", not the "how"
- Return ONLY the JSON object`

// trailTitleModel is the model hint for trail title generation.
// Haiku is fast (~1-2s) and cheap — trail titles are simple tasks.
const trailTitleModel = "haiku"

// TrailTitleResult contains the LLM-generated title and description for a trail.
type TrailTitleResult struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

// GenerateTrailTitle generates a title and description for a trail using the agent's
// text generation capability. Returns (nil, nil) if the agent doesn't support text generation.
func GenerateTrailTitle(ctx context.Context, transcriptBytes []byte, filesTouched []string, agentType agent.AgentType) (*TrailTitleResult, error) {
	// Get the active agent and check if it implements TextGenerator
	ag, err := agent.GetByAgentType(agentType)
	if err != nil {
		return nil, fmt.Errorf("agent not found: %w", err)
	}
	gen, ok := ag.(agent.TextGenerator)
	if !ok {
		// Agent does not support text generation: treat as non-fatal and return no result.
		return nil, nil //nolint:nilnil // nil result signals "not supported", not an error
	}

	// Build condensed transcript (reuse existing infrastructure)
	condensed, err := BuildCondensedTranscriptFromBytes(transcriptBytes, agentType)
	if err != nil {
		return nil, fmt.Errorf("failed to parse transcript: %w", err)
	}
	if len(condensed) == 0 {
		return nil, errors.New("transcript has no content")
	}

	input := Input{Transcript: condensed, FilesTouched: filesTouched}
	transcriptText := FormatCondensedTranscript(input)

	// Build prompt and call agent's TextGenerator
	prompt := fmt.Sprintf(trailTitlePromptTemplate, transcriptText)
	rawResult, err := gen.GenerateText(ctx, prompt, trailTitleModel)
	if err != nil {
		return nil, fmt.Errorf("text generation failed: %w", err)
	}

	// Parse JSON response (handle markdown code blocks)
	cleaned := extractJSONFromMarkdown(rawResult)
	var result TrailTitleResult
	if err := json.Unmarshal([]byte(cleaned), &result); err != nil {
		return nil, fmt.Errorf("failed to parse trail title JSON: %w", err)
	}

	return &result, nil
}

