200→//nolint:cyclop // sequential steps for creating a trail — splitting would obscure the flow
201→func runTrailCreate(w, errW io.Writer, title, body, base, branch, statusStr string, checkout bool) error {
202→	repo, err := strategy.OpenRepository(context.Background())
203→	if err != nil {
204→		return fmt.Errorf("failed to open repository: %w", err)
205→	}
206→
207→	// Determine base branch
208→	if base == "" {
209→		base = strategy.GetDefaultBranchName(repo)
210→		if base == "" {
211→			base = defaultBaseBranch
212→		}
213→	}
214→
215→	_, currentBranch, _ := IsOnDefaultBranch() //nolint:errcheck // best-effort detection
216→	interactive := !hasFlag("title") && !hasFlag("branch")
217→
218→	if interactive {
219→		// Interactive flow: title → body → branch (derived) → status
220→		if err := runTrailCreateInteractive(&title, &body, &branch, &statusStr); err != nil {
221→			return err
222→		}
223→	} else {
224→		// Non-interactive: derive missing values from provided flags
225→		if branch == "" {
226→			if hasFlag("title") {
227→				branch = slugifyTitle(title)
228→			} else {
229→				branch = currentBranch
230→			}
231→		}
232→		if title == "" {
233→			title = trail.HumanizeBranchName(branch)
234→		}
235→	}
236→	if branch == "" {
237→		return errors.New("branch name is required")
238→	}
239→
240→	// Create the branch if it doesn't exist
241→	needsCreation := branchNeedsCreation(repo, branch)
242→	if needsCreation {
243→		if err := createBranch(repo, branch); err != nil {
244→			return fmt.Errorf("failed to create branch %q: %w", branch, err)
245→		}
246→		fmt.Fprintf(w, "Created branch %s\n", branch)
247→	} else if currentBranch != branch {
248→		fmt.Fprintf(errW, "Note: trail will be created for branch %q (not the current branch)\n", branch)
249→	}
250→
251→	// Check if trail already exists for this branch
252→	store := trail.NewStore(repo)
253→	existing, err := store.FindByBranch(branch)
254→	if err == nil && existing != nil {
255→		fmt.Fprintf(w, "Trail already exists for branch %q (ID: %s)\n", branch, existing.TrailID)
256→		return nil
257→	}
258→
259→	// Determine status
260→	var trailStatus trail.Status
261→	if statusStr != "" {
262→		trailStatus = trail.Status(statusStr)
263→		if !trailStatus.IsValid() {
264→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
265→		}
266→	} else {
267→		trailStatus = trail.StatusDraft
268→	}
269→
270→	// Generate trail ID
271→	trailID, err := trail.GenerateID()
272→	if err != nil {
273→		return fmt.Errorf("failed to generate trail ID: %w", err)
274→	}
275→
276→	// Get author (GitHub username, falls back to git user.name)
277→	authorName := getTrailAuthor(repo)
278→
279→	now := time.Now()
280→	metadata := &trail.Metadata{
281→		TrailID:   trailID,
282→		Branch:    branch,
283→		Base:      base,
284→		Title:     title,
285→		Body:      body,
286→		Status:    trailStatus,
287→		Author:    authorName,
288→		Assignees: []string{},
289→		Labels:    []string{},
290→		CreatedAt: now,
291→		UpdatedAt: now,
292→	}
293→
294→	if err := store.Write(metadata, nil, nil); err != nil {
295→		return fmt.Errorf("failed to create trail: %w", err)
296→	}
297→
298→	fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", title, branch, trailID)
299→
300→	// Push the branch and trail data to origin
301→	if needsCreation {
302→		if err := pushBranchToOrigin(branch); err != nil {
303→			fmt.Fprintf(errW, "Warning: failed to push branch: %v\n", err)
304→		} else {
305→			fmt.Fprintf(w, "Pushed branch %s to origin\n", branch)
306→		}
307→	}
308→	if err := strategy.PushTrailsBranch(context.Background(), "origin"); err != nil {
309→		fmt.Fprintf(errW, "Warning: failed to push trail data: %v\n", err)
310→	}
311→
312→	// Checkout the branch if requested or prompted
313→	if needsCreation && currentBranch != branch {
314→		shouldCheckout := checkout
315→		if !shouldCheckout && !hasFlag("checkout") {
316→			// Interactive: ask whether to checkout
317→			form := NewAccessibleForm(
318→				huh.NewGroup(
319→					huh.NewConfirm().
320→						Title(fmt.Sprintf("Check out branch %s?", branch)).
321→						Value(&shouldCheckout),
322→				),
323→			)
324→			if formErr := form.Run(); formErr == nil && shouldCheckout {
325→				checkout = true
326→			}
327→		}
328→		if checkout {
329→			if err := CheckoutBranch(branch); err != nil {
330→				return fmt.Errorf("failed to checkout branch %q: %w", branch, err)
331→			}
332→			fmt.Fprintf(w, "Switched to branch %s\n", branch)
333→		}
334→	}
335→
336→	return nil
337→}
