354→	cmd.Flags().StringVar(&branch, "branch", "", "Branch to update trail for (defaults to current)")
355→	cmd.Flags().StringSliceVar(&labelAdd, "add-label", nil, "Add label(s)")
356→	cmd.Flags().StringSliceVar(&labelRemove, "remove-label", nil, "Remove label(s)")
