361→func runTrailUpdate(w io.Writer, statusStr, title, body, branch string, labelAdd, labelRemove []string) error {
362→	repo, err := strategy.OpenRepository(context.Background())
363→	if err != nil {
364→		return fmt.Errorf("failed to open repository: %w", err)
365→	}
366→
367→	// Determine branch
368→	if branch == "" {
369→		branch, err = GetCurrentBranch()
370→		if err != nil {
371→			return fmt.Errorf("failed to determine current branch: %w", err)
372→		}
373→	}
374→
375→	store := trail.NewStore(repo)
376→	metadata, err := store.FindByBranch(branch)
377→	if err != nil {
378→		return fmt.Errorf("failed to find trail: %w", err)
379→	}
380→	if metadata == nil {
381→		return fmt.Errorf("no trail found for branch %q", branch)
382→	}
383→
384→	// Interactive mode when no flags are provided
385→	noFlags := statusStr == "" && title == "" && body == "" && labelAdd == nil && labelRemove == nil
386→	if noFlags {
387→		// Build status options with current value as default.
388→		// Exclude "done" and "closed" unless the trail is already in that status
389→		// (otherwise the select would silently reset to the first option).
390→		var statusOptions []huh.Option[string]
391→		for _, s := range trail.ValidStatuses() {
392→			if (s == trail.StatusDone || s == trail.StatusClosed) && s != metadata.Status {
393→				continue
394→			}
395→			label := string(s)
396→			if s == metadata.Status {
397→				label += " (current)"
398→			}
399→			statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
400→		}
401→		statusStr = string(metadata.Status)
402→		title = metadata.Title
403→		body = metadata.Body
404→
405→		form := NewAccessibleForm(
406→			huh.NewGroup(
407→				huh.NewSelect[string]().
408→					Title("Status").
409→					Options(statusOptions...).
410→					Value(&statusStr),
411→				huh.NewInput().
412→					Title("Title").
413→					Value(&title),
414→				huh.NewText().
415→					Title("Body").
416→					Value(&body),
417→			),
418→		)
419→		if formErr := form.Run(); formErr != nil {
420→			return fmt.Errorf("form cancelled: %w", formErr)
421→		}
422→	}
423→
424→	// Validate status if provided
425→	if statusStr != "" {
426→		status := trail.Status(statusStr)
427→		if !status.IsValid() {
428→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
429→		}
430→	}
431→
432→	err = store.Update(metadata.TrailID, func(m *trail.Metadata) {
433→		if statusStr != "" {
434→			m.Status = trail.Status(statusStr)
435→		}
436→		if title != "" {
437→			m.Title = title
438→		}
439→		if body != "" {
440→			m.Body = body
441→		}
442→		for _, l := range labelAdd {
443→			if !containsString(m.Labels, l) {
444→				m.Labels = append(m.Labels, l)
445→			}
446→		}
447→		for _, l := range labelRemove {
448→			m.Labels = removeString(m.Labels, l)
449→		}
450→	})
451→	if err != nil {
452→		return fmt.Errorf("failed to update trail: %w", err)
453→	}
454→
455→	fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
456→	return nil
457→}
