574→// runTrailCreateInteractive runs the interactive form for trail creation.
575→// Prompts for title, body, branch (derived from title), and status.
576→func runTrailCreateInteractive(title, body, branch, statusStr *string) error {
577→	// Step 1: Title and body
578→	form := NewAccessibleForm(
579→		huh.NewGroup(
580→			huh.NewInput().
581→				Title("Trail title").
582→				Placeholder("What are you working on?").
583→				Value(title),
584→			huh.NewText().
585→				Title("Body (optional)").
586→				Value(body),
587→		),
588→	)
589→	if err := form.Run(); err != nil {
590→		return fmt.Errorf("form cancelled: %w", err)
591→	}
592→	*title = strings.TrimSpace(*title)
593→	if *title == "" {
594→		return errors.New("trail title is required")
595→	}
596→
597→	// Step 2: Branch (derived from title) and status
598→	suggested := slugifyTitle(*title)
599→	*branch = suggested
600→
601→	// Build status options, excluding done/closed
602→	var statusOptions []huh.Option[string]
603→	for _, s := range trail.ValidStatuses() {
604→		if s == trail.StatusDone || s == trail.StatusClosed {
605→			continue
606→		}
607→		statusOptions = append(statusOptions, huh.NewOption(string(s), string(s)))
608→	}
609→	if *statusStr == "" {
610→		*statusStr = string(trail.StatusDraft)
611→	}
612→
613→	form = NewAccessibleForm(
614→		huh.NewGroup(
615→			huh.NewInput().
616→				Title("Branch name").
617→				Placeholder(suggested).
618→				Value(branch),
619→			huh.NewSelect[string]().
620→				Title("Status").
621→				Options(statusOptions...).
622→				Value(statusStr),
623→		),
624→	)
625→	if err := form.Run(); err != nil {
626→		return fmt.Errorf("form cancelled: %w", err)
627→	}
628→	*branch = strings.TrimSpace(*branch)
629→	if *branch == "" {
630→		*branch = suggested
631→	}
632→	return nil
633→}
634→
635→// fetchTrailsBranch fetches the remote trails branch so we see trails from collaborators.
636→// Best-effort: silently ignores errors (e.g., no remote, no network).
637→func fetchTrailsBranch() {
638→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
639→	defer cancel()
640→	branchName := paths.TrailsBranchName
641→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
642→	//nolint:gosec // G204: branchName is a constant from paths package
643→	cmd := exec.CommandContext(ctx, "git", "fetch", "origin", refSpec)
644→	// Ensure non-interactive fetch in hook/agent contexts
645→	cmd.Stdin = nil
646→	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
647→	_ = cmd.Run() //nolint:errcheck // best-effort fetch
648→}
649→
650→// getTrailAuthor returns the GitHub username for the trail author.
651→// Falls back to git user.name if gh CLI is unavailable or not authenticated.
652→func getTrailAuthor(repo *git.Repository) string {
653→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
654→	defer cancel()
655→	cmd := exec.CommandContext(ctx, "gh", "api", "user", "-q", ".login")
656→	if output, err := cmd.Output(); err == nil {
657→		if login := strings.TrimSpace(string(output)); login != "" {
658→			return login
659→		}
660→	}
661→	name, _ := strategy.GetGitAuthorFromRepo(repo)
662→	return name
663→}
664→
665→// slugifyTitle converts a title string into a branch-friendly slug.
666→// Example: "Add user authentication" -> "add-user-authentication"
667→func slugifyTitle(title string) string {
668→	s := strings.ToLower(strings.TrimSpace(title))
669→	// Replace spaces and underscores with hyphens
670→	s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
671→	// Remove anything that's not alphanumeric, hyphen, or slash
672→	var b strings.Builder
673→	prevHyphen := false
674→	for _, r := range s {
675→		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
676→			b.WriteRune(r)
677→			prevHyphen = false
678→		} else if r == '-' && !prevHyphen {
679→			b.WriteRune('-')
680→			prevHyphen = true
681→		}
682→	}
683→	return strings.Trim(b.String(), "-")
684→}
685→
686→// branchNeedsCreation checks if a branch exists locally.
687→func branchNeedsCreation(repo *git.Repository, branchName string) bool {
688→	_, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
689→	return err != nil
690→}
691→
692→// createBranch creates a new local branch pointing at HEAD without checking it out.
693→func createBranch(repo *git.Repository, branchName string) error {
694→	head, err := repo.Head()
695→	if err != nil {
696→		return fmt.Errorf("failed to get HEAD: %w", err)
697→	}
698→	ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
699→	if err := repo.Storer.SetReference(ref); err != nil {
700→		return fmt.Errorf("failed to create branch ref: %w", err)
701→	}
702→	return nil
703→}
704→
705→// pushBranchToOrigin pushes a branch to the origin remote.
706→func pushBranchToOrigin(branchName string) error {
707→	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
708→	defer cancel()
709→	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "-u", "origin", branchName)
710→	if output, err := cmd.CombinedOutput(); err != nil {
711→		return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
712→	}
713→	return nil
714→}
